"""Snapshot and composer tests against a synthetic corporate template generated by
``tests.support.office_template_fixture``, so nothing is read from outside the repository."""

from __future__ import annotations

from pathlib import Path

import pytest

from app.services.office_identity.template_snapshot import (
    build_template_snapshot,
    layout_by_key,
    layouts_by_shape,
)
from tests.services.office_identity.office_identity_template_snapshot_support import (  # noqa: F401
    brand_snapshot,
    brand_template,
)
from tests.support.office_template_fixture import BRAND_ACCENT1, BRAND_FONT, THEME_NAME, write_template

#: Brand evidence: these values prove resolution goes through the master, not ``ppt/theme/theme1.xml``.
BRAND_THEME_NAME = THEME_NAME


#: Office defaults — seeing these means theme resolution regressed.
OFFICE_DEFAULT_ACCENT1 = "#5B9BD5"


OFFICE_DEFAULT_FONT = "Calibri Light"


BRAND_LAYOUT_COUNT = 15


LIBRARY_LAYOUT_COUNT = 19


@pytest.fixture(scope="module")
def library_template(tmp_path_factory) -> Path:
    return write_template(tmp_path_factory.mktemp("library") / "library.potx", "library")


@pytest.fixture(scope="module")
def library_snapshot(library_template) -> dict:
    return build_template_snapshot(library_template)


@pytest.mark.parametrize("fixture_name", ["brand_snapshot", "library_snapshot"])
def test_theme_is_resolved_through_the_master_not_theme1(fixture_name, request):
    snapshot = request.getfixturevalue(fixture_name)
    theme = snapshot["theme"]

    assert theme["theme_name"] == BRAND_THEME_NAME
    assert theme["fonts"]["major"] == BRAND_FONT
    assert theme["fonts"]["minor"] == BRAND_FONT
    assert theme["colors"]["accent1"]["hex"] == BRAND_ACCENT1
    # the core finding: never the Office defaults
    assert theme["colors"]["accent1"]["hex"] != OFFICE_DEFAULT_ACCENT1
    assert theme["fonts"]["major"] != OFFICE_DEFAULT_FONT
    # and the resolution path is auditable
    assert theme["theme_source"].startswith("ppt/presentation.xml -> ppt/slideMasters/")
    assert not theme["theme_source"].startswith("fallback:")


def test_brand_layout_catalog(brand_snapshot):  # noqa: F811
    assert brand_snapshot["summary"]["layout_count"] == BRAND_LAYOUT_COUNT
    assert brand_snapshot["summary"]["master_count"] == 1


def test_library_layout_catalog(library_snapshot):
    assert library_snapshot["summary"]["layout_count"] == LIBRARY_LAYOUT_COUNT
    assert library_snapshot["summary"]["master_count"] == 2


@pytest.mark.parametrize("fixture_name", ["brand_snapshot", "library_snapshot"])
def test_icons_three_topics_capacity(fixture_name, request):
    snapshot = request.getfixturevalue(fixture_name)
    layout = layout_by_key(snapshot, "icons-3-topics")

    assert layout is not None
    assert layout["name"] == "Icons 3 Topics"
    assert layout["content_shape"] == "icons_3"
    assert layout["capacity"]["content_units"] == 3
    assert layout["capacity"]["body_slots"] == 6
    body_idx = sorted(slot["idx"] for slot in layout["slots"] if slot["role"] == "content")
    assert body_idx == [16, 17, 18, 19, 20, 21]


@pytest.mark.parametrize("fixture_name", ["brand_snapshot", "library_snapshot"])
def test_title_slide_present(fixture_name, request):
    snapshot = request.getfixturevalue(fixture_name)
    layout = layout_by_key(snapshot, "title-slide")

    assert layout is not None
    assert layout["name"] == "Title Slide"
    assert layout["content_shape"] == "title_slide"
    assert layout["capacity"]["title_slots"] == 1
    assert layout["capacity"]["subtitle_slots"] == 1


def test_layout_keys_are_unique_across_masters(library_snapshot):
    keys = [layout["key"] for layout in library_snapshot["layouts"]]
    assert len(keys) == len(set(keys))
    # duplicate names across the two masters are disambiguated, not dropped
    assert layout_by_key(library_snapshot, "title-slide--m2") is not None


def test_picture_slots_carry_geometry_and_aspect_ratio(brand_snapshot):  # noqa: F811
    grids = layouts_by_shape(brand_snapshot, "image_grid_3")
    assert grids, "template must expose a 3-image grid layout"

    picture_slots = [slot for slot in grids[0]["slots"] if slot["role"] == "picture"]
    assert len(picture_slots) == 3
    for slot in picture_slots:
        assert isinstance(slot["x_emu"], int)
        assert slot["w_emu"] > 0 and slot["h_emu"] > 0
        assert slot["aspect_ratio"] == pytest.approx(slot["w_emu"] / slot["h_emu"], rel=1e-3)
        assert slot["geometry_source"] in {"layout", "master"}


def test_sample_slides_and_icons_are_metadata_only(library_snapshot):
    assert library_snapshot["sample_slides"] == 18
    assert library_snapshot["summary"]["svg_media_count"] == 8

    icons = library_snapshot["icons"]
    assert icons, "sample template must yield a searchable icon catalog"
    assert len(icons) <= library_snapshot["summary"]["svg_media_count"]
    assert len(icons) == len({icon["slug"] for icon in icons})
    assert icons == sorted(icons, key=lambda item: (item["category_key"], item["slug"]))
    for icon in icons:
        assert icon["part"].startswith("ppt/media/")
        assert icon["tags"]
        # metadata only — no binary payload travels in the brief
        assert set(icon) == {"slug", "name", "category", "category_key", "part", "tags"}


def test_snapshot_is_deterministic(brand_template, brand_snapshot):  # noqa: F811
    again = build_template_snapshot(brand_template)
    assert again == brand_snapshot


def test_brand_template_has_no_warnings(brand_snapshot):  # noqa: F811
    assert brand_snapshot["warnings"] == []


def test_rejects_non_presentation_package(tmp_path):
    bogus = tmp_path / "not-a-deck.potx"
    bogus.write_bytes(b"PK\x03\x04 not a real package")
    with pytest.raises((ValueError, OSError)):
        build_template_snapshot(bogus)
